<script setup>
import {reactive,ref} from 'vue';import {useWorkspace} from '../stores/workspace.js';import Icon from '../components/Icon.vue';import Dialog from '../components/Dialog.vue';
const store=useWorkspace(),form=reactive({...store.settings}),saved=ref(false),resetOpen=ref(false),error=ref('');function save(){if(!form.name.trim()||!form.company.trim()||!/^\S+@\S+\.\S+$/.test(form.email)){error.value='Please provide a name, company and valid email.';return;}store.settings={...form,name:form.name.trim(),company:form.company.trim()};error.value='';saved.value=true;store.notify('Workspace settings saved.');}
</script>
<template><div class="page-heading"><div><div class="greeting">MAKE YOURSELF AT HOME</div><h1>Workspace settings.</h1><p>A few details to make Dispatch feel like yours.</p></div></div><div class="settings-layout"><section class="panel"><div class="panel-heading"><div><h2>Your workspace</h2><p>These details are stored on this device.</p></div><Icon name="Settings"/></div><form @submit.prevent="save" class="settings-form"><label>Your name<input v-model="form.name" required maxlength="80" autocomplete="name" @input="saved=false"></label><label>Company name<input v-model="form.company" required maxlength="80" autocomplete="organization" @input="saved=false"></label><label>Email address<input v-model="form.email" type="email" required maxlength="150" autocomplete="email" @input="saved=false"></label><div class="setting-toggle"><div><b>Compact tables</b><p>Show more shipments with tighter row spacing.</p></div><input type="checkbox" v-model="form.compact" role="switch" aria-label="Compact tables" @change="saved=false"></div><p class="field-error" v-if="error" role="alert">{{error}}</p><button class="btn primary"><Icon :name="saved?'Check':'Check'"/>{{saved?'Saved':'Save preferences'}}</button></form></section><div><section class="panel settings-info"><span class="green-icon"><Icon name="Package" :size="25"/></span><h2>A demo with real interactions.</h2><p>Your changes stay in this browser. There is no account, server sync or real shipment tracking.</p><ul><li>Vue 3 & Composition API</li><li>Pinia state management</li><li>Vue Router with shareable filters</li><li>Responsive, accessible components</li><li>Unit and store integration tests</li></ul></section><section class="panel reset-panel"><h2>Start fresh</h2><p>Restore the original 32 demo shipments. Your profile preferences will be kept.</p><button class="btn" @click="resetOpen=true"><Icon name="RefreshCw"/>Reset demo shipments</button></section></div></div><Dialog v-if="resetOpen" title="Restore demo shipments?" @close="resetOpen=false"><p class="info-copy">Your created shipments and edits will be replaced with the original sample dataset. Profile settings will be kept.</p><div class="dialog-actions"><button class="btn" @click="resetOpen=false">Cancel</button><button class="btn primary" @click="store.reset();resetOpen=false">Restore demo data</button></div></Dialog></template>
